begin;
set local search_path=public,extensions;
select plan(12);
select has_table('public','studio_scenario_versions','Versioned scenarios exist');
select has_table('public','studio_worksheets','Owner heads exist');
select has_table('public','studio_worksheet_revisions','Immutable revisions exist');
select is((select experience_kind from public.course_versions where id='system-design-studio-v1'),'studio','Course uses Studio experience');
insert into auth.users(id,email) values('a4600000-0000-0000-0000-000000000001','studio-policy-a@example.test'),('a4600000-0000-0000-0000-000000000002','studio-policy-b@example.test');
update public.profiles set goal='Learn careful workload estimation' where user_id in ('a4600000-0000-0000-0000-000000000001','a4600000-0000-0000-0000-000000000002');
set local role anon;
select throws_ok($$select public.get_studio_workshop('system-design-studio-v1','campus-events-v1')$$,'42501','permission denied for function get_studio_workshop','Anonymous RPC denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.enrol_course('system-design-studio-v1')$$,'No JavaScript prerequisite');
select is(public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000003','{"functionalRequirements":"Browse events","exclusions":"Ticketing","latencyTargetMs":200,"availabilityTargetPercent":99.9,"assumptions":"Illustrative defaults","explanation":"","workload":{"dailyActiveUsers":100000,"requestsPerUserPerDay":20,"peakFactor":5,"readPercentage":90,"readResponseBytes":20000,"writePayloadBytes":2000,"retentionDays":30}}'::jsonb)->>'revision','1','First revision saved');
select is(public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000003','{"functionalRequirements":"Browse events","exclusions":"Ticketing","latencyTargetMs":200,"availabilityTargetPercent":99.9,"assumptions":"Illustrative defaults","explanation":"","workload":{"dailyActiveUsers":100000,"requestsPerUserPerDay":20,"peakFactor":5,"readPercentage":90,"readResponseBytes":20000,"writePayloadBytes":2000,"retentionDays":30}}'::jsonb)->>'revision','1','Identical retry returned original');
select is((select count(*) from public.studio_worksheet_revisions),1::bigint,'Retry saved once');
select throws_ok($$select public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000004','{"functionalRequirements":"Browse events","exclusions":"Ticketing","latencyTargetMs":200,"availabilityTargetPercent":99.9,"assumptions":"Illustrative defaults","explanation":"","workload":{"dailyActiveUsers":100000,"requestsPerUserPerDay":20,"peakFactor":5,"readPercentage":90,"readResponseBytes":20000,"writePayloadBytes":2000,"retentionDays":30}}'::jsonb)$$,'40001','A newer worksheet revision exists','Stale revision rejected');
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.studio_worksheet_revisions),0::bigint,'Other learner sees no revisions');
select is((select count(*) from public.attempts),0::bigint,'Saving awarded no practice grade');
reset role;
select * from finish();
rollback;
